"use strict";App.Http.Login=function(){return{validate:function(username,password,captcha,altchaPayload){var url=App.Utils.Url.siteUrl("login/validate"),data={csrf_token:vars("csrf_token"),username:username,password:password};return captcha&&(data.captcha=captcha),altchaPayload&&(data.altcha_payload=altchaPayload),$.post(url,data)}}}();